
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_xc_th1_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_xc_th1", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.756722625701310e+00, -4.652725435479042e+00, -4.507083437386809e+00, -4.305693757656900e+00, -4.032495002330720e+00, -3.672510974119677e+00, -3.218893254965086e+00, -2.685500656820636e+00, -2.121996385463099e+00, -1.606028760615785e+00, -1.118664845394449e+00, -7.465361583009319e-01, -6.549601119602942e-01, -5.370996966902093e-01, -3.923241011491218e-01, -2.564405596826651e-01, -1.505215930670914e-01, -6.757779845671476e-02, 6.881415966977512e-03, 6.646021756510530e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


